package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.DiagnosisWorkflowEventEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.DiagnosisWorkflowEventMapper; import org.springframework.stereotype.Repository; import java.util.List;
@Repository public class MybatisWorkflowEventRepository implements WorkflowEventRepository { private final DiagnosisWorkflowEventMapper mapper; public MybatisWorkflowEventRepository(DiagnosisWorkflowEventMapper mapper){this.mapper=mapper;} public int append(DiagnosisWorkflowEventEntity e){return mapper.insert(e);} public List<DiagnosisWorkflowEventEntity> findByWorkflowIdOrderBySequence(String id){return mapper.selectList(new LambdaQueryWrapper<DiagnosisWorkflowEventEntity>().eq(DiagnosisWorkflowEventEntity::getWorkflowId,id).orderByAsc(DiagnosisWorkflowEventEntity::getEventSequence));} }
